    )

STATE_MAP = {
    "Pending": {
        "roles": ["Accountant"],
        "notify_owner": False,
        "headline": "A new material request needs your review.",
    },
    "Accountant Approval": {
        "roles": ["Finance Officer"],
        "notify_owner": False,
        "headline": "Approved by the Accountant. Awaiting Finance Officer review.",
    },
    "Finance Officer Approval": {
        "roles": ["Director"],
        "notify_owner": False,
        "headline": "Approved by the Finance Officer. Awaiting Director approval.",
    },
    "Director Approval": {
        "roles": ["Director"],
        "notify_owner": True,
        "headline": "Awaiting final sign-off from the Director.",
    },
    "Approved": {
        "roles": ["Accountant", "Finance Officer"],
        "notify_owner": True,
        "headline": "This request has been fully approved.",
    },
    "Rejected": {
        "roles": [],
        "notify_owner": True,
        "headline": "This request has been rejected.",
    },
    "Cancelled": {
        "roles": [],
        "notify_owner": True,
        "headline": "This request has been cancelled.",
    },
}

PRINT_FORMAT = "Other Material Request"

before = doc.get_doc_before_save()
previous_state = before.workflow_state if before else None
config = STATE_MAP.get(doc.workflow_state)

if config and doc.workflow_state != previous_state:

    # --- recipients -------------------------------------------------
    candidates = []
    for role in config["roles"]:
        for user in frappe.get_all(
            "Has Role",
            filters={"role": role, "parenttype": "User"},
            pluck="parent",
        ):
            if user not in candidates:
                candidates.append(user)

    if config["notify_owner"] and doc.owner not in candidates:
        candidates.append(doc.owner)

    recipients = []
    if candidates:
        for user in frappe.get_all(
            "User",
            filters={"name": ["in", candidates], "enabled": 1},
            pluck="name",
        ):
            if "@" in user and user not in ("Administrator", "Guest"):
                recipients.append(user)

    if recipients:
        # --- attachments --------------------------------------------
        attachments = []
        for file_id in frappe.get_all(
            "File",
            filters={
                "attached_to_doctype": doc.doctype,
                "attached_to_name": doc.name,
            },
            pluck="name",
        ):
            attachments.append({"fid": file_id})

        # Only attach the PDF if the print format really exists,
        # otherwise sendmail raises and the whole transition fails.
        if frappe.db.exists("Print Format", PRINT_FORMAT):
            attachments.append({
                "print_format_attachment": 1,
                "doctype": doc.doctype,
                "name": doc.name,
                "print_format": PRINT_FORMAT,
                "lang": "en",
            })

        # --- body ---------------------------------------------------
        link = frappe.utils.get_url("http://104.237.9.160:81/app/other-material-request/" + doc.name)
        from_state = previous_state or "New"

        rows = ""
        for row in (doc.get("items") or []):
            item = row.get("item_name") or row.get("item_code") or ""
            qty = row.get("qty") or ""
            uom = row.get("uom") or ""
            rows += f"<tr><td>{item}</td><td align='right'>{qty}</td><td>{uom}</td></tr>"

        items_table = ""
        if rows:
            items_table = (
                "<p><b>Items</b></p>"
                "<table border='1' cellpadding='6' "
                "style='border-collapse:collapse;font-size:12px'>"
                "<tr><th>Item</th><th>Qty</th><th>UOM</th></tr>"
                + rows + "</table>"
            )

        message = f"""
        <p>{config["headline"]}</p>
        <table cellpadding="6" style="border-collapse:collapse;font-size:13px">
          <tr><td><b>Request</b></td><td>{doc.name}</td></tr>
          <tr><td><b>Status</b></td><td>{from_state} &rarr; <b>{doc.workflow_state}</b></td></tr>
          <tr><td><b>Raised by</b></td><td>{frappe.db.get_value("User", doc.owner, "full_name")}</td></tr>
        </table>
        {items_table}
        <p><a href="{link}" style="background:#171717;color:#fff;padding:8px 16px;
           border-radius:6px;text-decoration:none;display:inline-block">Open the request</a></p>
        """

        frappe.sendmail(
            recipients=recipients,
            subject=f"[{doc.workflow_state}] Other Material Request {doc.name}",
            message=message,
            attachments=attachments,
            reference_doctype=doc.doctype,
            reference_name=doc.name,
            now=False,
        )
